SOURCES = {"models/fcff_dcf.py":"\"\"\"Five-year discounted cash flow (DCF) valuation. USD amounts in millions.\"\"\"\n\n# ==================== EDITABLE INPUTS ====================\nstarting_fcff = 100.0             # USD millions, at Year 0\nyearly_growth_rates = [0.08, 0.06, 0.05, 0.04, 0.03]  # Years 1-5\nwacc = 0.10\nterminal_growth = 0.03\nnon_operating_cash = 50.0         # USD millions\ndebt = 300.0                       # USD millions\ndiluted_shares = 50.0             # millions of shares\n# =======================================================\n\n\ndef main():\n    if len(yearly_growth_rates) != 5:\n        raise SystemExit(\"Error: Provide exactly five yearly growth rates.\")\n    if terminal_growth >= wacc:\n        raise SystemExit(\"Error: Terminal growth must be less than WACC.\")\n    if wacc <= -1:\n        raise SystemExit(\"Error: WACC must be greater than -100%.\")\n    if diluted_shares <= 0:\n        raise SystemExit(\"Error: Diluted shares must be greater than zero.\")\n\n    fcff = starting_fcff\n    cash_flows = []\n    for growth in yearly_growth_rates:\n        fcff *= 1 + growth\n        cash_flows.append(fcff)\n\n    pv_explicit_fcff = sum(\n        flow / (1 + wacc) ** year\n        for year, flow in enumerate(cash_flows, start=1)\n    )\n    terminal_value_year_5 = cash_flows[-1] * (1 + terminal_growth) / (wacc - terminal_growth)\n    pv_terminal_value = terminal_value_year_5 / (1 + wacc) ** 5\n    enterprise_value = pv_explicit_fcff + pv_terminal_value\n    equity_value = enterprise_value + non_operating_cash - debt\n    value_per_share = equity_value / diluted_shares\n    terminal_share_of_ev = pv_terminal_value / enterprise_value if enterprise_value != 0 else float(\"nan\")\n\n    for year, flow in enumerate(cash_flows, start=1):\n        print(f\"FCFF Year {year} (USD millions): {flow:.4f}\")\n    print(f\"PV of Years 1-5 FCFF (USD millions): {pv_explicit_fcff:.4f}\")\n    print(f\"Terminal value at Year 5 (USD millions): {terminal_value_year_5:.4f}\")\n    print(f\"PV of terminal value (USD millions): {pv_terminal_value:.4f}\")\n    print(f\"Enterprise value (USD millions): {enterprise_value:.4f}\")\n    print(f\"Equity value (USD millions): {equity_value:.4f}\")\n    print(f\"Value per diluted share (USD): {value_per_share:.4f}\")\n    print(f\"PV of terminal value / enterprise value: {terminal_share_of_ev:.4f}\")\n\n\nif __name__ == \"__main__\":\n    main()\n","references/abg_lab07_calculator.py":"\"\"\"Simple peer P/E valuation using only Python's standard library.\"\"\"\n\nfrom fractions import Fraction\n\n\n# EDIT THESE INPUTS. Use numbers or decimal strings; use None for missing data.\nTARGET = {\n    \"name\": \"Asbury Automotive (ABG)\",\n    \"diluted_eps\": \"21.50\",\n}\n\nPEERS = [\n    {\"name\": \"AutoNation (AN)\", \"price\": \"169.84\", \"diluted_eps\": \"16.92\"},\n    {\"name\": \"Group 1 Automotive (GPI)\", \"price\": \"421.48\", \"diluted_eps\": \"36.81\"},\n]\n\n\ndef positive_fraction(value):\n    \"\"\"Return an exact positive Fraction, or None for missing/invalid values.\"\"\"\n    if value is None or isinstance(value, bool):\n        return None\n    try:\n        number = Fraction(str(value).strip())\n    except (ValueError, ZeroDivisionError):\n        return None\n    return number if number > 0 else None\n\n\ndef median(values):\n    ordered = sorted(values)\n    middle = len(ordered) // 2\n    if len(ordered) % 2:\n        return ordered[middle]\n    return (ordered[middle - 1] + ordered[middle]) / 2\n\n\ndef format_fixed(value, places):\n    \"\"\"Format a Fraction with round-half-even, without changing stored precision.\"\"\"\n    scale = 10**places\n    scaled_numerator = value.numerator * scale\n    quotient, remainder = divmod(scaled_numerator, value.denominator)\n    twice_remainder = remainder * 2\n    if twice_remainder > value.denominator or (\n        twice_remainder == value.denominator and quotient % 2\n    ):\n        quotient += 1\n    whole, fraction = divmod(quotient, scale)\n    if places == 0:\n        return str(whole)\n    return f\"{whole}.{fraction:0{places}d}\"\n\n\ndef dollar(value):\n    sign = \"-\" if value < 0 else \"\"\n    return f\"{sign}${format_fixed(abs(value), 2)}\"\n\n\ndef unique_peers(target_name, peers):\n    target_key = str(target_name).strip().casefold()\n    seen = set()\n    result = []\n    for index, peer in enumerate(peers, 1):\n        name = str(peer.get(\"name\", \"\")).strip()\n        key = name.casefold()\n        if not key:\n            name = f\"Unnamed peer {index}\"\n            key = name.casefold()\n        if key == target_key:\n            print(f\"Excluded {name}: same as target.\")\n        elif key in seen:\n            print(f\"Excluded {name}: duplicate peer.\")\n        else:\n            seen.add(key)\n            result.append({**peer, \"name\": name})\n    return result\n\n\ndef usable_multiples(peers):\n    usable = []\n    for peer in peers:\n        price = positive_fraction(peer.get(\"price\"))\n        eps = positive_fraction(peer.get(\"diluted_eps\"))\n        if price is not None and eps is not None:\n            usable.append((peer[\"name\"], price / eps))\n    return usable\n\n\ndef median_implied_price(peers, target_eps):\n    multiples = [multiple for _, multiple in usable_multiples(peers)]\n    if not multiples or target_eps is None:\n        return None\n    return median(multiples) * target_eps\n\n\ndef main():\n    target_name = str(TARGET.get(\"name\", \"Target\")).strip() or \"Target\"\n    target_eps = positive_fraction(TARGET.get(\"diluted_eps\"))\n    peers = unique_peers(target_name, PEERS)\n\n    print(f\"\\nTarget: {target_name}\")\n    if target_eps is None:\n        print(\"Target diluted EPS: not meaningful (missing or nonpositive)\")\n    else:\n        print(f\"Target diluted EPS: {format_fixed(target_eps, 6)}\")\n\n    print(\"\\nPeer P/E multiples:\")\n    usable = []\n    for peer in peers:\n        price = positive_fraction(peer.get(\"price\"))\n        eps = positive_fraction(peer.get(\"diluted_eps\"))\n        if price is None or eps is None:\n            reasons = []\n            if price is None:\n                reasons.append(\"price\")\n            if eps is None:\n                reasons.append(\"diluted EPS\")\n            print(\n                f\"  {peer['name']}: not meaningful \"\n                f\"(missing or nonpositive {' and '.join(reasons)})\"\n            )\n        else:\n            multiple = price / eps\n            usable.append((peer[\"name\"], multiple))\n            print(f\"  {peer['name']}: {format_fixed(multiple, 6)}x\")\n\n    print(\"\\nValuation:\")\n    if not usable:\n        print(\"  No usable peers.\")\n    else:\n        multiples = [multiple for _, multiple in usable]\n        median_multiple = median(multiples)\n        print(f\"  Median peer P/E: {format_fixed(median_multiple, 6)}x\")\n        if target_eps is None:\n            print(\"  Implied price calculation: not meaningful (target diluted EPS is missing or nonpositive).\")\n        elif len(multiples) == 1:\n            print(f\"  Reference estimate (no range): {dollar(median_multiple * target_eps)}\")\n        else:\n            print(f\"  Minimum implied price: {dollar(min(multiples) * target_eps)}\")\n            print(f\"  Median implied price:  {dollar(median_multiple * target_eps)}\")\n            print(f\"  Maximum implied price: {dollar(max(multiples) * target_eps)}\")\n\n    print(\"\\nPeer-removal sensitivity (median-implied price):\")\n    if not peers:\n        print(\"  No peers to remove.\")\n        return\n\n    full_estimate = median_implied_price(peers, target_eps)\n    for removed_index, peer in enumerate(peers):\n        remaining = peers[:removed_index] + peers[removed_index + 1 :]\n        remaining_usable = usable_multiples(remaining)\n        if not remaining_usable:\n            print(f\"  Remove {peer['name']}: no estimate (no usable peers remain).\")\n            continue\n        estimate = median_implied_price(remaining, target_eps)\n        if estimate is None or full_estimate is None:\n            print(\n                f\"  Remove {peer['name']}: estimate and dollar change not meaningful \"\n                \"(target diluted EPS is missing or nonpositive).\"\n            )\n            continue\n        change = estimate - full_estimate\n        descriptor = \"reference estimate\" if len(remaining_usable) == 1 else \"estimate\"\n        change_sign = \"+\" if change > 0 else \"\"\n        print(\n            f\"  Remove {peer['name']}: {dollar(estimate)} ({descriptor}); \"\n            f\"change {change_sign}{dollar(change)}\"\n        )\n\n\nif __name__ == \"__main__\":\n    main()\n","references/peer_valuation_template.py":"\"\"\"Simple peer P/E valuation using only Python's standard library.\"\"\"\n\nfrom fractions import Fraction\n\n\n# EDIT THESE INPUTS. Use numbers or decimal strings; use None for missing data.\nTARGET = {\n    \"name\": \"TargetCo\",\n    \"diluted_eps\": \"4.25\",\n}\n\nPEERS = [\n    {\"name\": \"Peer A\", \"price\": \"84.50\", \"diluted_eps\": \"4.10\"},\n    {\"name\": \"Peer B\", \"price\": \"102.75\", \"diluted_eps\": \"5.25\"},\n    {\"name\": \"Peer C\", \"price\": \"76.20\", \"diluted_eps\": \"3.60\"},\n]\n\n\ndef positive_fraction(value):\n    \"\"\"Return an exact positive Fraction, or None for missing/invalid values.\"\"\"\n    if value is None or isinstance(value, bool):\n        return None\n    try:\n        number = Fraction(str(value).strip())\n    except (ValueError, ZeroDivisionError):\n        return None\n    return number if number > 0 else None\n\n\ndef median(values):\n    ordered = sorted(values)\n    middle = len(ordered) // 2\n    if len(ordered) % 2:\n        return ordered[middle]\n    return (ordered[middle - 1] + ordered[middle]) / 2\n\n\ndef format_fixed(value, places):\n    \"\"\"Format a Fraction with round-half-even, without changing stored precision.\"\"\"\n    scale = 10**places\n    scaled_numerator = value.numerator * scale\n    quotient, remainder = divmod(scaled_numerator, value.denominator)\n    twice_remainder = remainder * 2\n    if twice_remainder > value.denominator or (\n        twice_remainder == value.denominator and quotient % 2\n    ):\n        quotient += 1\n    whole, fraction = divmod(quotient, scale)\n    if places == 0:\n        return str(whole)\n    return f\"{whole}.{fraction:0{places}d}\"\n\n\ndef dollar(value):\n    sign = \"-\" if value < 0 else \"\"\n    return f\"{sign}${format_fixed(abs(value), 2)}\"\n\n\ndef unique_peers(target_name, peers):\n    target_key = str(target_name).strip().casefold()\n    seen = set()\n    result = []\n    for index, peer in enumerate(peers, 1):\n        name = str(peer.get(\"name\", \"\")).strip()\n        key = name.casefold()\n        if not key:\n            name = f\"Unnamed peer {index}\"\n            key = name.casefold()\n        if key == target_key:\n            print(f\"Excluded {name}: same as target.\")\n        elif key in seen:\n            print(f\"Excluded {name}: duplicate peer.\")\n        else:\n            seen.add(key)\n            result.append({**peer, \"name\": name})\n    return result\n\n\ndef usable_multiples(peers):\n    usable = []\n    for peer in peers:\n        price = positive_fraction(peer.get(\"price\"))\n        eps = positive_fraction(peer.get(\"diluted_eps\"))\n        if price is not None and eps is not None:\n            usable.append((peer[\"name\"], price / eps))\n    return usable\n\n\ndef median_implied_price(peers, target_eps):\n    multiples = [multiple for _, multiple in usable_multiples(peers)]\n    if not multiples or target_eps is None:\n        return None\n    return median(multiples) * target_eps\n\n\ndef main():\n    target_name = str(TARGET.get(\"name\", \"Target\")).strip() or \"Target\"\n    target_eps = positive_fraction(TARGET.get(\"diluted_eps\"))\n    peers = unique_peers(target_name, PEERS)\n\n    print(f\"\\nTarget: {target_name}\")\n    if target_eps is None:\n        print(\"Target diluted EPS: not meaningful (missing or nonpositive)\")\n    else:\n        print(f\"Target diluted EPS: {format_fixed(target_eps, 6)}\")\n\n    print(\"\\nPeer P/E multiples:\")\n    usable = []\n    for peer in peers:\n        price = positive_fraction(peer.get(\"price\"))\n        eps = positive_fraction(peer.get(\"diluted_eps\"))\n        if price is None or eps is None:\n            reasons = []\n            if price is None:\n                reasons.append(\"price\")\n            if eps is None:\n                reasons.append(\"diluted EPS\")\n            print(\n                f\"  {peer['name']}: not meaningful \"\n                f\"(missing or nonpositive {' and '.join(reasons)})\"\n            )\n        else:\n            multiple = price / eps\n            usable.append((peer[\"name\"], multiple))\n            print(f\"  {peer['name']}: {format_fixed(multiple, 6)}x\")\n\n    print(\"\\nValuation:\")\n    if not usable:\n        print(\"  No usable peers.\")\n    else:\n        multiples = [multiple for _, multiple in usable]\n        median_multiple = median(multiples)\n        print(f\"  Median peer P/E: {format_fixed(median_multiple, 6)}x\")\n        if target_eps is None:\n            print(\"  Implied price calculation: not meaningful (target diluted EPS is missing or nonpositive).\")\n        elif len(multiples) == 1:\n            print(f\"  Reference estimate (no range): {dollar(median_multiple * target_eps)}\")\n        else:\n            print(f\"  Minimum implied price: {dollar(min(multiples) * target_eps)}\")\n            print(f\"  Median implied price:  {dollar(median_multiple * target_eps)}\")\n            print(f\"  Maximum implied price: {dollar(max(multiples) * target_eps)}\")\n\n    print(\"\\nPeer-removal sensitivity (median-implied price):\")\n    if not peers:\n        print(\"  No peers to remove.\")\n        return\n\n    full_estimate = median_implied_price(peers, target_eps)\n    for removed_index, peer in enumerate(peers):\n        remaining = peers[:removed_index] + peers[removed_index + 1 :]\n        remaining_usable = usable_multiples(remaining)\n        if not remaining_usable:\n            print(f\"  Remove {peer['name']}: no estimate (no usable peers remain).\")\n            continue\n        estimate = median_implied_price(remaining, target_eps)\n        if estimate is None or full_estimate is None:\n            print(\n                f\"  Remove {peer['name']}: estimate and dollar change not meaningful \"\n                \"(target diluted EPS is missing or nonpositive).\"\n            )\n            continue\n        change = estimate - full_estimate\n        descriptor = \"reference estimate\" if len(remaining_usable) == 1 else \"estimate\"\n        change_sign = \"+\" if change > 0 else \"\"\n        print(\n            f\"  Remove {peer['name']}: {dollar(estimate)} ({descriptor}); \"\n            f\"change {change_sign}{dollar(change)}\"\n        )\n\n\nif __name__ == \"__main__\":\n    main()\n","models/walmart_peer_pe.py":"\"\"\"Peer P/E valuation for Walmart (standard library only).\n\nEdit TARGET and PEERS below. Enter numeric values as strings so Decimal keeps\ntheir exact entered precision. Price means current share price; diluted_eps\nmust be diluted EPS on the same basis and period for every company.\n\"\"\"\n\nfrom decimal import Decimal, InvalidOperation\nfrom statistics import median\n\n\n# ----------------------------- EDIT INPUTS HERE -----------------------------\nTARGET = {\n    \"ticker\": \"WMT\",\n    # Walmart FY2026 GAAP diluted EPS, reported before September 9, 2026.\n    \"diluted_eps\": \"2.73\",\n    \"eps_fiscal_period\": \"Fiscal year ended January 31, 2026\",\n    \"eps_publication_date\": \"March 2026\",\n}\n\n# Walmart reverse DCF inputs copied from Reverse DCF.md. These use a later\n# valuation date than the EPS above, so the program labels the dates clearly.\nREVERSE_DCF = {\n    \"valuation_date\": \"September 9, 2026\",\n    \"share_price\": \"105.83\",\n    \"implied_share_price\": \"105.83\",\n    \"implied_five_year_fcff_growth\": \"22.3\",\n    \"terminal_growth_rate\": \"2.5\",\n    \"wacc\": \"7.0\",\n}\n\n# Frozen comparison: September 9, 2026 unadjusted closing prices (USD),\n# divided by the most recent annual GAAP diluted EPS then publicly available.\n# Peers require independent business-model comparability judgments.\n# Source: https://stockanalysis.com/stocks/{ticker}/history/\n# Annual EPS sources:\n# COST https://www.sec.gov/Archives/edgar/data/909832/000090983225000157/costannualreport2025.pdf\n# TGT https://corporate.target.com/investors/annual/2025-annual-report/10-k-report/10-k-part-ii/item-8-financial-statements-and-supplementary-data\n# DG https://www.sec.gov/Archives/edgar/data/29534/000110465926032325/dg-20260130x10k.htm\n# DLTR https://www.sec.gov/Archives/edgar/data/935703/000093570326000056/ars2025dltr.pdf\n# BJ https://www.sec.gov/Archives/edgar/data/1531152/000153115226000003/bj-202601312025x8kex991.htm\n# WMT https://www.sec.gov/Archives/edgar/data/104169/000010416926000055/R26.htm\nPEERS = [\n    {\"ticker\": \"COST\", \"price\": \"902.60\", \"diluted_eps\": \"18.21\"}, # FY2025\n    {\"ticker\": \"TGT\", \"price\": \"157.52\", \"diluted_eps\": \"8.13\"},   # FY2025\n    {\"ticker\": \"DG\", \"price\": \"124.57\", \"diluted_eps\": \"6.85\"},     # FY2025\n    {\"ticker\": \"DLTR\", \"price\": \"118.39\", \"diluted_eps\": \"6.22\"},   # FY2025; discontinued operations affect comparability\n    {\"ticker\": \"BJ\", \"price\": \"88.51\", \"diluted_eps\": \"4.38\"},     # FY2025\n]\n# ---------------------------------------------------------------------------\n\n\ndef positive_decimal(value):\n    \"\"\"Return a positive finite Decimal, or None when it is not meaningful.\"\"\"\n    if value is None or isinstance(value, bool):\n        return None\n    try:\n        number = Decimal(str(value))\n    except (InvalidOperation, ValueError):\n        return None\n    return number if number.is_finite() and number > 0 else None\n\n\ndef normalized_ticker(value):\n    return str(value).strip().upper()\n\n\ndef unique_peers(peers, target_ticker):\n    \"\"\"Keep the first occurrence of each peer, case-insensitively.\"\"\"\n    result = []\n    seen = set()\n    for peer in peers:\n        ticker = normalized_ticker(peer.get(\"ticker\", \"\"))\n        if not ticker or ticker == target_ticker or ticker in seen:\n            continue\n        seen.add(ticker)\n        result.append(\n            {\n                \"ticker\": ticker,\n                \"price\": peer.get(\"price\"),\n                \"diluted_eps\": peer.get(\"diluted_eps\"),\n            }\n        )\n    return result\n\n\ndef peer_multiple(peer):\n    price = positive_decimal(peer[\"price\"])\n    eps = positive_decimal(peer[\"diluted_eps\"])\n    return None if price is None or eps is None else price / eps\n\n\ndef fmt_multiple(value):\n    return f\"{value:.6f}x\"\n\n\ndef fmt_price(value):\n    return f\"${value:.2f}\"\n\n\ndef fmt_signed_price(value):\n    sign = \"+\" if value >= 0 else \"-\"\n    return f\"{sign}${abs(value):.2f}\"\n\n\ndef print_side_by_side_dcf_and_eps(target_eps):\n    \"\"\"Print the reverse-DCF headline and historical EPS in adjacent columns.\"\"\"\n    dcf_price = positive_decimal(REVERSE_DCF.get(\"implied_share_price\"))\n    dcf_price_label = fmt_price(dcf_price) if dcf_price is not None else \"not meaningful\"\n    eps_label = fmt_price(target_eps) if target_eps is not None else \"not meaningful\"\n    left_width = 48\n\n    rows = [\n        (\"Walmart reverse DCF\", \"Walmart diluted EPS\"),\n        (\n            f\"Implied share price: {dcf_price_label}\",\n            f\"Diluted EPS: {eps_label}\",\n        ),\n        (\n            f\"Valuation date: {REVERSE_DCF.get('valuation_date', 'unresolved')}\",\n            TARGET.get(\"eps_fiscal_period\", \"Fiscal period: unresolved\"),\n        ),\n        (\n            \"Implied five-year FCFF growth: \"\n            f\"{REVERSE_DCF.get('implied_five_year_fcff_growth', 'unresolved')}%\",\n            f\"Publication date: {TARGET.get('eps_publication_date', 'unresolved')}\",\n        ),\n        (\n            f\"Terminal growth: {REVERSE_DCF.get('terminal_growth_rate', 'unresolved')}%\",\n            \"Different dates; no direct DCF/EPS multiple.\",\n        ),\n    ]\n\n    print(\"\\nReverse DCF and EPS:\")\n    print(f\"  {rows[0][0]:<{left_width}} | {rows[0][1]}\")\n    print(f\"  {'-' * left_width}-+-{'-' * 43}\")\n    for left, right in rows[1:]:\n        print(f\"  {left:<{left_width}} | {right}\")\n\n\ndef main():\n    target_ticker = normalized_ticker(TARGET.get(\"ticker\", \"\")) or \"TARGET\"\n    target_eps = positive_decimal(TARGET.get(\"diluted_eps\"))\n    peers = unique_peers(PEERS, target_ticker)\n    multiples = [(peer[\"ticker\"], peer_multiple(peer)) for peer in peers]\n    valid = [(ticker, multiple) for ticker, multiple in multiples if multiple is not None]\n\n    print(f\"Target: {target_ticker}\")\n    print(\n        f\"Target diluted EPS: {TARGET.get('diluted_eps')}\"\n        if target_eps is not None\n        else \"Target diluted EPS: not meaningful\"\n    )\n    print_side_by_side_dcf_and_eps(target_eps)\n    print(\"\\nPeer P/E multiples:\")\n    if not peers:\n        print(\"  No peer inputs after deduplication and target exclusion.\")\n    for ticker, multiple in multiples:\n        label = fmt_multiple(multiple) if multiple is not None else \"not meaningful\"\n        print(f\"  {ticker}: {label}\")\n\n    print(\"\\nValuation:\")\n    if not valid:\n        print(\"  No usable peers.\")\n        full_estimate = None\n    else:\n        values = [multiple for _, multiple in valid]\n        median_multiple = median(values)\n        full_estimate = median_multiple * target_eps if target_eps is not None else None\n\n        if len(values) == 1:\n            print(f\"  Peer P/E: {fmt_multiple(values[0])}\")\n            if full_estimate is None:\n                print(\"  Reference estimate: not meaningful (target EPS is missing or nonpositive).\")\n            else:\n                print(f\"  Reference estimate: {fmt_price(full_estimate)} (no range)\")\n        else:\n            minimum_multiple = min(values)\n            maximum_multiple = max(values)\n            print(f\"  Minimum peer P/E: {fmt_multiple(minimum_multiple)}\")\n            print(f\"  Median peer P/E:  {fmt_multiple(median_multiple)}\")\n            print(f\"  Maximum peer P/E: {fmt_multiple(maximum_multiple)}\")\n            if target_eps is None:\n                print(\"  Minimum implied price: not meaningful (target EPS is missing or nonpositive).\")\n                print(\"  Median implied price:  not meaningful (target EPS is missing or nonpositive).\")\n                print(\"  Maximum implied price: not meaningful (target EPS is missing or nonpositive).\")\n            else:\n                print(f\"  Minimum implied price: {fmt_price(minimum_multiple * target_eps)}\")\n                print(f\"  Median implied price:  {fmt_price(full_estimate)}\")\n                print(f\"  Maximum implied price: {fmt_price(maximum_multiple * target_eps)}\")\n\n    print(\"\\nPeer-removal sensitivity:\")\n    if not peers:\n        print(\"  No peers to remove.\")\n    for removed_peer in peers:\n        remaining = [\n            multiple\n            for ticker, multiple in multiples\n            if ticker != removed_peer[\"ticker\"] and multiple is not None\n        ]\n        prefix = f\"  Remove {removed_peer['ticker']}: \"\n        if not remaining:\n            print(prefix + \"no estimate\")\n        elif target_eps is None or full_estimate is None:\n            print(prefix + \"not meaningful (target EPS is missing or nonpositive)\")\n        else:\n            removal_estimate = median(remaining) * target_eps\n            dollar_change = removal_estimate - full_estimate\n            print(\n                prefix\n                + f\"{fmt_price(removal_estimate)}; change {fmt_signed_price(dollar_change)}\"\n            )\n\n\nif __name__ == \"__main__\":\n    main()\n","models/walmart_proforma.py":"\"\"\"\n5-year pro forma (income statement, balance sheet, cash flow) and FCFE valuation.\nCompany: Walmart Inc.   Opening balance sheet: 10-K for fiscal year ended Jan 31, 2026.\nAll money in $ millions, except per-share values.\nStandard library only.\n \nYear labels: \"2026\" = the fiscal year that starts in 2026 (FY2027, ends Jan 31, 2027), ... \"2030\" = FY2031.\n\"\"\"\n \nYEARS = [2026, 2027, 2028, 2029, 2030]\n \n# ----------------------------------------------------------------------------\n# OPENING BALANCE SHEET  (Jan 31, 2026, 10-K / Q4 FY26 earnings release)\n# ----------------------------------------------------------------------------\nOPEN = {\n    \"cash\": 10727.0,\n    \"inventory\": 58851.0,\n    \"ppe\": 136083.0,\n    \"other_assets\": 79007.0,   # plug: total assets 284,668 less the three lines above\n    \"floor_plan\": 63061.0,     # Walmart has no floor plan; this slot carries accounts payable\n    \"debt\": 38166.0,           # long-term debt incl. current portion (3,542 + 34,624)\n    \"revolver\": 6596.0,        # short-term borrowings\n    \"other_liab\": 70958.0,     # plug: total liabilities 178,781 less payables, debt, revolver\n    \"equity\": 105887.0,        # total equity incl. noncontrolling interest\n    \"revenue\": 713163.0,       # FY26 total revenues\n}\n \n# ----------------------------------------------------------------------------\n# ASSUMPTIONS (one value per year unless scalar)\n# ----------------------------------------------------------------------------\nA = {\n    \"growth\":        [0.045, 0.045, 0.040, 0.040, 0.035],\n    \"gross_margin\":  [0.2495, 0.2500, 0.2505, 0.2510, 0.2515],  # FY26 actual 24.93%\n    \"sga_ratio\":     [0.7520, 0.7510, 0.7500, 0.7490, 0.7480],  # SG&A / gross profit, ex-depreciation\n    \"dep_ratio\":     [0.110] * 5,                               # depreciation / opening PP&E\n    \"impairment\":    [0.0] * 5,\n    \"capex\":         [27500.0, 28000.0, 28500.0, 29000.0, 29500.0],\n    \"repayment\":     [3500.0] * 5,\n    \"buyback\":       [8000.0] * 5,      # shareholder payout (dividends ~ $0.99 x 7.97bn sh)\n    \"inv_days\":      [40.1] * 5,        # inventory / cost of sales x 365\n    \"floor_ratio\":   [1.0715] * 5,      # payables / inventory\n    \"tax_rate\":      [0.244] * 5,\n}\nOTHER_WC_PCT = 0.008        # other assets rise 0.8% of each $ of revenue growth\nRATE_FLOOR = 0.0            # payables carry no interest\nRATE_DEBT = 0.055\nRATE_REVOLVER = 0.045\nMIN_CASH = 8000.0\nCOST_OF_EQUITY = 0.075\nTERMINAL_GROWTH = 0.030\nSHARES = 7972.4             # millions, as of Mar 11, 2026 (10-K cover)\n \n \n# ----------------------------------------------------------------------------\n# MODEL\n# ----------------------------------------------------------------------------\ndef project():\n    prev = dict(OPEN)\n    out = []\n    for i, yr in enumerate(YEARS):\n        r = {\"year\": yr}\n        # --- income statement\n        r[\"revenue\"] = prev[\"revenue\"] * (1 + A[\"growth\"][i])\n        r[\"gross_profit\"] = r[\"revenue\"] * A[\"gross_margin\"][i]\n        r[\"cogs\"] = r[\"revenue\"] - r[\"gross_profit\"]\n        r[\"sga\"] = r[\"gross_profit\"] * A[\"sga_ratio\"][i]\n        r[\"dep\"] = prev[\"ppe\"] * A[\"dep_ratio\"][i]\n        r[\"impair\"] = A[\"impairment\"][i]\n        r[\"op_income\"] = r[\"gross_profit\"] - r[\"sga\"] - r[\"dep\"] - r[\"impair\"]\n        r[\"interest\"] = (prev[\"floor_plan\"] * RATE_FLOOR + prev[\"debt\"] * RATE_DEBT\n                         + prev[\"revolver\"] * RATE_REVOLVER)\n        r[\"pretax\"] = r[\"op_income\"] - r[\"interest\"]\n        r[\"tax\"] = max(0.0, r[\"pretax\"]) * A[\"tax_rate\"][i]\n        r[\"net_income\"] = r[\"pretax\"] - r[\"tax\"]\n \n        # --- balance sheet except cash\n        r[\"inventory\"] = r[\"cogs\"] * A[\"inv_days\"][i] / 365\n        r[\"floor_plan\"] = r[\"inventory\"] * A[\"floor_ratio\"][i]\n        r[\"capex\"] = A[\"capex\"][i]\n        r[\"ppe\"] = prev[\"ppe\"] + r[\"capex\"] - r[\"dep\"]\n        r[\"d_owc\"] = OTHER_WC_PCT * (r[\"revenue\"] - prev[\"revenue\"])\n        r[\"other_assets\"] = prev[\"other_assets\"] + r[\"d_owc\"] - r[\"impair\"]\n        r[\"repay\"] = A[\"repayment\"][i]\n        r[\"debt\"] = prev[\"debt\"] - r[\"repay\"]\n        r[\"other_liab\"] = prev[\"other_liab\"]\n        r[\"buyback\"] = A[\"buyback\"][i]\n        r[\"equity\"] = prev[\"equity\"] + r[\"net_income\"] - r[\"buyback\"]\n \n        # --- free cash flow to equity\n        r[\"d_inv\"] = r[\"inventory\"] - prev[\"inventory\"]\n        r[\"d_floor\"] = r[\"floor_plan\"] - prev[\"floor_plan\"]\n        r[\"fcfe\"] = (r[\"net_income\"] + r[\"dep\"] + r[\"impair\"] - r[\"capex\"]\n                     - r[\"d_inv\"] - r[\"d_owc\"] + r[\"d_floor\"] - r[\"repay\"])\n \n        # --- cash and revolver\n        pre = prev[\"cash\"] + r[\"fcfe\"] - r[\"buyback\"]\n        if pre < MIN_CASH:\n            draw, rep = MIN_CASH - pre, 0.0\n        else:\n            draw, rep = 0.0, min(prev[\"revolver\"], pre - MIN_CASH)\n        r[\"rev_draw\"], r[\"rev_repay\"] = draw, rep\n        r[\"revolver\"] = prev[\"revolver\"] + draw - rep\n        r[\"cash\"] = pre + draw - rep\n \n        # --- totals and checks\n        r[\"assets\"] = r[\"cash\"] + r[\"inventory\"] + r[\"ppe\"] + r[\"other_assets\"]\n        r[\"liabilities\"] = r[\"floor_plan\"] + r[\"debt\"] + r[\"revolver\"] + r[\"other_liab\"]\n        r[\"gap\"] = r[\"assets\"] - r[\"liabilities\"] - r[\"equity\"]\n        r[\"cash_ok\"] = r[\"cash\"] >= MIN_CASH - 1e-6\n        out.append(r)\n        prev = r\n    return out\n \n \n# ----------------------------------------------------------------------------\n# PRINTING\n# ----------------------------------------------------------------------------\ndef table(title, rows, open_col=None):\n    print(\"\\n\" + title)\n    head = f\"{'':32}\" + (f\"{'Open':>12}\" if open_col is not None else \"\") + \"\".join(f\"{y:>12}\" for y in YEARS)\n    print(head)\n    print(\"-\" * len(head))\n    for label, vals, op in rows:\n        line = f\"{label:32}\"\n        if open_col is not None:\n            line += f\"{op:>12,.1f}\" if op is not None else f\"{'':>12}\"\n        line += \"\".join(f\"{v:>12,.1f}\" for v in vals)\n        print(line)\n \n \ndef col(res, k):\n    return [r[k] for r in res]\n \n \ndef print_statements(res):\n    neg = lambda k: [-r[k] for r in res]\n    table(\"INCOME STATEMENT ($mm)\", [\n        (\"Revenue\", col(res, \"revenue\"), None),\n        (\"Gross profit\", col(res, \"gross_profit\"), None),\n        (\"SG&A\", neg(\"sga\"), None),\n        (\"Depreciation\", neg(\"dep\"), None),\n        (\"Impairment\", neg(\"impair\"), None),\n        (\"Operating income\", col(res, \"op_income\"), None),\n        (\"Interest\", neg(\"interest\"), None),\n        (\"Pretax income\", col(res, \"pretax\"), None),\n        (\"Tax\", neg(\"tax\"), None),\n        (\"Net income\", col(res, \"net_income\"), None),\n    ])\n    o = OPEN\n    o_assets = o[\"cash\"] + o[\"inventory\"] + o[\"ppe\"] + o[\"other_assets\"]\n    o_liab = o[\"floor_plan\"] + o[\"debt\"] + o[\"revolver\"] + o[\"other_liab\"]\n    table(\"BALANCE SHEET ($mm)\", [\n        (\"Cash\", col(res, \"cash\"), o[\"cash\"]),\n        (\"Inventory\", col(res, \"inventory\"), o[\"inventory\"]),\n        (\"PP&E\", col(res, \"ppe\"), o[\"ppe\"]),\n        (\"Other assets\", col(res, \"other_assets\"), o[\"other_assets\"]),\n        (\"Total assets\", col(res, \"assets\"), o_assets),\n        (\"Floor plan (accounts payable)\", col(res, \"floor_plan\"), o[\"floor_plan\"]),\n        (\"Debt\", col(res, \"debt\"), o[\"debt\"]),\n        (\"Revolver\", col(res, \"revolver\"), o[\"revolver\"]),\n        (\"Other liabilities\", col(res, \"other_liab\"), o[\"other_liab\"]),\n        (\"Total liabilities\", col(res, \"liabilities\"), o_liab),\n        (\"Equity\", col(res, \"equity\"), o[\"equity\"]),\n    ], open_col=True)\n    table(\"CASH FLOW ($mm)\", [\n        (\"Net income\", col(res, \"net_income\"), None),\n        (\"+ Depreciation\", col(res, \"dep\"), None),\n        (\"+ Impairment\", col(res, \"impair\"), None),\n        (\"- Capex\", neg(\"capex\"), None),\n        (\"- Change in inventory\", neg(\"d_inv\"), None),\n        (\"- Change in other WC\", neg(\"d_owc\"), None),\n        (\"+ Change in floor plan\", col(res, \"d_floor\"), None),\n        (\"- Debt repayment\", neg(\"repay\"), None),\n        (\"Free cash flow to equity\", col(res, \"fcfe\"), None),\n        (\"- Buyback / payout\", neg(\"buyback\"), None),\n        (\"+ Revolver draw\", col(res, \"rev_draw\"), None),\n        (\"- Revolver repayment\", neg(\"rev_repay\"), None),\n        (\"Ending cash\", col(res, \"cash\"), None),\n    ])\n \n \ndef print_checks(res):\n    print(\"\\nCHECKS\")\n    print(f\"{'':32}\" + \"\".join(f\"{y:>12}\" for y in YEARS))\n    print(f\"{'Assets - liabilities - equity':32}\" + \"\".join(f\"{r['gap']:>12.6f}\" for r in res))\n    print(f\"{'Cash >= minimum (%.0f)' % MIN_CASH:32}\" + \"\".join(f\"{str(r['cash_ok']):>12}\" for r in res))\n \n \ndef assert_balanced(res, tol=1e-6):\n    for r in res:\n        if abs(r[\"gap\"]) > tol:\n            raise AssertionError(f\"Year {r['year']}: balance sheet out of balance by {r['gap']:.6f}\")\n        if not r[\"cash_ok\"]:\n            raise AssertionError(f\"Year {r['year']}: cash {r['cash']:.1f} is below minimum {MIN_CASH:.1f}\")\n \n \n# ----------------------------------------------------------------------------\n# VALUATION\n# ----------------------------------------------------------------------------\ndef value(res):\n    ke, g = COST_OF_EQUITY, TERMINAL_GROWTH\n    pv_flows = sum(r[\"fcfe\"] / (1 + ke) ** (t + 1) for t, r in enumerate(res))\n    last = res[-1]\n    tv = (last[\"fcfe\"] + last[\"repay\"]) * (1 + g) / (ke - g)\n    pv_tv = tv / (1 + ke) ** 5\n    eq = pv_flows + pv_tv\n    return eq, pv_tv / eq, eq / SHARES\n \n \ndef main():\n    res = project()\n    print_statements(res)\n    print_checks(res)\n    assert_balanced(res)\n    eq, share_tv, vps = value(res)\n    print(\"\\nVALUATION\")\n    print(f\"Equity value ($mm):            {eq:,.1f}\")\n    print(f\"Share of value after 2030:     {share_tv:.1%}\")\n    print(f\"Value per share ($):           {vps:,.2f}\")\n \n \nif __name__ == \"__main__\":\n    main()\n","models/walmart_sensitivity.py":"\"\"\"Lab 11: reproducible one-driver-at-a-time Walmart sensitivity.\nUses the actual pro-forma engine; no invented output numbers.\nRun from repository root: python models/walmart_sensitivity.py\n\"\"\"\nimport copy\nimport importlib.util\nfrom pathlib import Path\n\nsource = Path(__file__).with_name(\"walmart_proforma.py\")\nspec = importlib.util.spec_from_file_location(\"walmart_proforma\", source)\nmodel = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(model)\n\nBASE = copy.deepcopy(model.A)\n# Judgement ranges are illustrative until supported by historical evidence.\nSHIFTS = {\"gross_margin\": 0.005, \"sga_ratio\": 0.01}\nTOLERANCE = 1e-6\n\ndef assert_close(actual, expected, label):\n    if abs(actual - expected) > TOLERANCE:\n        raise AssertionError(f\"{label}: actual {actual}, expected {expected}\")\n\n\ndef evaluate(assumptions):\n    model.A = copy.deepcopy(assumptions)\n    rows = model.project()\n    model.assert_balanced(rows)\n    # Independently reconcile cash movement to the balance-sheet cash each year.\n    previous_cash = model.OPEN[\"cash\"]\n    for row in rows:\n        cash_from_flows = (previous_cash + row[\"fcfe\"] - row[\"buyback\"]\n                           + row[\"rev_draw\"] - row[\"rev_repay\"])\n        assert_close(row[\"cash\"], cash_from_flows,\n                     f\"Fiscal-start year {row['year']} ending cash tie\")\n        previous_cash = row[\"cash\"]\n    equity, terminal_share, price = model.value(rows)\n    return {\n        \"operating_income\": rows[-1][\"op_income\"],\n        \"fcfe\": rows[-1][\"fcfe\"],\n        \"price\": price,\n        \"balance_gap\": max(abs(r[\"gap\"]) for r in rows),\n        \"terminal_share\": terminal_share,\n    }\n\ndef main():\n    try:\n        baseline = evaluate(BASE)\n        print(\"BASE\", baseline)\n        print(\"NOTE: This reruns the CURRENT walmart_proforma.py assumptions; \"\n              \"older saved Lab 11 figures are not its validation target.\")\n        for key, shift in SHIFTS.items():\n            if key not in BASE or len(BASE[key]) != len(model.YEARS):\n                raise ValueError(f\"Invalid driver path or year count: {key}\")\n            if shift <= 0:\n                raise ValueError(f\"Shift must be positive: {key}\")\n            print(\"\\nDRIVER:\", key, \"shift\", shift, \"absolute ratio points\")\n            cases = {}\n            for name, direction in ((\"lower\", -1), (\"base\", 0), (\"higher\", 1)):\n                inputs = copy.deepcopy(BASE)\n                inputs[key] = [v + direction * shift for v in BASE[key]]\n                result = evaluate(inputs)\n                if name == \"base\":\n                    for metric in (\"operating_income\", \"fcfe\", \"price\", \"terminal_share\"):\n                        assert_close(result[metric], baseline[metric],\n                                     f\"{key} base {metric}\")\n                cases[name] = result\n                print(name, \"values:\", inputs[key])\n                print(\" outputs:\", result)\n                print(\" changes from base:\", {\n                    k: result[k] - baseline[k]\n                    for k in (\"operating_income\", \"fcfe\", \"price\")\n                })\n            print(\"OUTPUT SPANS:\", {\n                k: max(v[k] for v in cases.values()) - min(v[k] for v in cases.values())\n                for k in (\"operating_income\", \"fcfe\", \"price\")\n            })\n        restored = evaluate(BASE)\n        for key in (\"operating_income\", \"fcfe\", \"price\"):\n            assert_close(restored[key], baseline[key], \"Base restoration: \" + key)\n        print(\"\\nRESTORED BASE PASS\", restored)\n    finally:\n        model.A = BASE\n\nif __name__ == \"__main__\":\n    main()\n"}

ORDER = ["models/fcff_dcf.py","references/abg_lab07_calculator.py","references/peer_valuation_template.py","models/walmart_peer_pe.py","models/walmart_proforma.py","models/walmart_sensitivity.py"]

def execute(path, *, as_main=True):
    source = SOURCES[path]
    namespace = {"__name__": "__main__" if as_main else path.replace("/", "_"),
                 "__file__": path}
    # The original sensitivity script loads a neighboring Python file.
    # Replace ONLY that import block with a model assembled from the embedded source.
    if path == "models/walmart_sensitivity.py":
        start = source.index('source = Path(__file__).with_name("walmart_proforma.py")')
        end = source.index("BASE = copy.deepcopy(model.A)")
        module = types.ModuleType("walmart_proforma_embedded")
        exec(compile(SOURCES["models/walmart_proforma.py"], "models/walmart_proforma.py", "exec"),
             module.__dict__)
        namespace["model"] = module
        source = source[:start] + source[end:]
    exec(compile(source, path, "exec"), namespace)

def main():
    selection = sys.argv[1:] if len(sys.argv) > 1 else ORDER
    unknown = [item for item in selection if item not in SOURCES]
    if unknown:
        print("Unknown script(s):", ", ".join(unknown), file=sys.stderr)
        print("Available:", ", ".join(ORDER), file=sys.stderr)
        return 2
    failures = []
    for path in selection:
        print("\n" + "=" * 72 + "\nRUNNING: " + path + "\n" + "=" * 72, flush=True)
        try:
            execute(path)
        except Exception as exc:
            failures.append((path, exc))
            import traceback
            traceback.print_exc()
    print("\n" + "=" * 72)
    print(f"COMPLETED: {len(selection)-len(failures)}/{len(selection)} scripts succeeded.")
    for path, exc in failures:
        print(f"FAILED: {path}: {type(exc).__name__}: {exc}")
    return 1 if failures else 0

if __name__ == "__main__":
    sys.exit(main())
